const messageId = $('Set Email').item.json.messageId;
const threadId  = $('Set Email').item.json.threadId;
const body      = $json.replyMessage;

const emailLines = [
  'MIME-Version: 1.0',
  'Content-Type: text/plain; charset=UTF-8',
  'To: ' + to,
  'Subject: ' + subject,
  'In-Reply-To: ' + messageId,
  'References: ' + messageId,
  '',
  body
];

const raw = Buffer.from(emailLines.join('\r\n'))
  .toString('base64')
  .replace(/\+/g, '-')
  .replace(/\//g, '_')
  .replace(/=+$/, '');

return { ...$json, threadId, raw };

const html = ($input.first().json.data || "").toLowerCase();

let liveShipmentStatus = "unknown";

// Define patterns with word boundaries to avoid substring false matches
const patterns = [
  { regex: /\bout for delivery\b/i, status: "out_for_delivery" },
  { regex: /\bshipment delivered\b/i, status: "delivered" },
  { regex: /\bdelivered\b/i, status: "delivered", exclude: /\bexpected delivery\b|\bdelivery date\b|\bdelivery partner\b/i },
  { regex: /\bin transit\b/i, status: "in_transit" },
  { regex: /\bready for pickup\b/i, status: "ready_for_pickup" },
  { regex: /\brto\b/i, status: "rto" },
  { regex: /\bundelivered\b/i, status: "undelivered" }
];

for (const p of patterns) {
  if (p.regex.test(html)) {
    // If there's an exclusion pattern and it matches, skip this status
    if (p.exclude && p.exclude.test(html)) {
      continue;
    }
    liveShipmentStatus = p.status;
    break; // First match wins (priority order)
  }
}

// Fallback: if still unknown but contains "delivered" without the exclusion patterns,
// we already caught it via the "delivered" pattern above. This is safe.

return {
  ...$('Match Order').first().json,
  liveShipmentStatus,
  trackingHtmlChecked: true
};

