// If we have a token and it was fetched less than 23 hours ago, use it
if (globalData.accessToken && globalData.tokenTimestamp) {
  const now = Date.now();
  const ageMs = now - globalData.tokenTimestamp;
  const maxAgeMs = 23 * 60 * 60 * 1000; // 23 hours in ms

  if (ageMs < maxAgeMs) {
    // Token is still valid – output it directly and STOP the Token node from running
    return [{
      json: {
        access_token: globalData.accessToken,
        fromCache: true
      }
    }];
  }
}

// No valid cached token – continue to the Token node
return $input.all();

